// Package setdata holds the per-set booster specs the draft stack plays
// with: one embedded JSON file per set, generated by internal/gen from the
// compliance manifest plus a hand-authored header, and committed.
//
// The package is pure: it reads nothing but its embedded files and imports
// nothing but the standard library and limited.
package setdata

import (
	"bytes"
	"embed"
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	"github.com/adams-shaun/gorge/limited"
)

//go:embed sets/*.json
var sets embed.FS

// SheetCard is one card on a booster sheet: the set's printing of the card
// that the pack generator draws by name.
type SheetCard struct {
	Name   string         `json:"name"`
	Number string         `json:"number"`
	Rarity limited.Rarity `json:"rarity"`
}

// RareMythic is the weight pair a rare-or-mythic slot splits on.
type RareMythic struct {
	RareWeight   int `json:"rare_weight"`
	MythicWeight int `json:"mythic_weight"`
}

// Weights is a wildcard slot's rarity distribution; the three sum to 1.
type Weights struct {
	Common     float64 `json:"common"`
	Uncommon   float64 `json:"uncommon"`
	RareMythic float64 `json:"rare_mythic"`
}

// Slot is one line of a pack's recipe: either a named sheet drawn Count
// times (optionally colour-balanced), a rare-or-mythic split, or a wildcard
// rarity roll. Exactly one of Sheet, RareMythic and Wildcard is set.
type Slot struct {
	Sheet          string      `json:"sheet,omitempty"`
	Count          int         `json:"count"`
	BalanceColours bool        `json:"balance_colours,omitempty"`
	RareMythic     *RareMythic `json:"rare_mythic,omitempty"`
	Wildcard       *Weights    `json:"wildcard,omitempty"`
}

// Spec is one set's booster spec.
type Spec struct {
	Code     string                 `json:"code"`
	Name     string                 `json:"name"`
	PackSize int                    `json:"pack_size"`
	MainMax  int                    `json:"main_max"`
	Sheets   map[string][]SheetCard `json:"sheets"`
	Slots    []Slot                 `json:"slots"`
	Source   string                 `json:"source"`
}

// Load returns the embedded, validated booster spec for the set code
// ("FDN", "BLB", ...).
func Load(code string) (Spec, error) {
	if code == "" || strings.ContainsAny(code, "/\\.") {
		return Spec{}, fmt.Errorf("setdata: bad set code %q", code)
	}
	b, err := sets.ReadFile("sets/" + code + ".json")
	if err != nil {
		return Spec{}, fmt.Errorf("setdata: unknown set %q", code)
	}
	var spec Spec
	if err := unmarshalStrict(b, &spec); err != nil {
		return Spec{}, fmt.Errorf("setdata: %s: %w", code, err)
	}
	if err := spec.Validate(); err != nil {
		return Spec{}, fmt.Errorf("setdata: %s: %w", code, err)
	}
	return spec, nil
}

// unmarshalStrict decodes v, refusing fields the spec types do not declare,
// so a generator/spec drift fails at Load instead of silently dropping data.
func unmarshalStrict(b []byte, v any) error {
	dec := json.NewDecoder(bytes.NewReader(b))
	dec.DisallowUnknownFields()
	return dec.Decode(v)
}

// Codes returns the set codes with an embedded spec, sorted.
func Codes() []string {
	entries, err := sets.ReadDir("sets")
	if err != nil {
		return nil
	}
	var codes []string
	for _, e := range entries {
		name := e.Name()
		if !strings.HasSuffix(name, ".json") {
			continue
		}
		codes = append(codes, strings.TrimSuffix(name, ".json"))
	}
	sort.Strings(codes)
	return codes
}

// Validate checks a spec's internal consistency: the slot counts fill the
// pack, every sheet is non-empty and referenced only where it exists, the
// wildcard weights sum to 1, and no card appears on two sheets or twice on
// one.
func (s *Spec) Validate() error {
	if s.Code == "" || s.Name == "" {
		return fmt.Errorf("spec needs a code and a name")
	}
	if s.PackSize <= 0 || s.MainMax <= 0 {
		return fmt.Errorf("pack_size and main_max must be positive")
	}
	if len(s.Sheets) == 0 {
		return fmt.Errorf("spec has no sheets")
	}
	total := 0
	for i, slot := range s.Slots {
		kinds := 0
		if slot.Sheet != "" {
			kinds++
		}
		if slot.RareMythic != nil {
			kinds++
		}
		if slot.Wildcard != nil {
			kinds++
		}
		if kinds != 1 {
			return fmt.Errorf("slot %d must set exactly one of sheet/rare_mythic/wildcard", i)
		}
		if slot.Count <= 0 {
			return fmt.Errorf("slot %d count must be positive", i)
		}
		total += slot.Count
		if slot.RareMythic != nil && (slot.RareMythic.RareWeight <= 0 || slot.RareMythic.MythicWeight <= 0) {
			return fmt.Errorf("slot %d rare_mythic weights must be positive", i)
		}
		if w := slot.Wildcard; w != nil {
			sum := w.Common + w.Uncommon + w.RareMythic
			if diff := sum - 1; diff > 1e-9 || diff < -1e-9 {
				return fmt.Errorf("slot %d wildcard weights sum to %g, want 1", i, sum)
			}
		}
		if slot.Sheet != "" {
			if _, ok := s.Sheets[slot.Sheet]; !ok {
				return fmt.Errorf("slot %d names missing sheet %q", i, slot.Sheet)
			}
		}
	}
	if total != s.PackSize {
		return fmt.Errorf("slot counts sum to %d, want pack_size %d", total, s.PackSize)
	}
	seen := map[string]string{}
	for sheet, cards := range s.Sheets {
		if len(cards) == 0 {
			return fmt.Errorf("sheet %q is empty", sheet)
		}
		for _, c := range cards {
			if c.Name == "" {
				return fmt.Errorf("sheet %q has a nameless card", sheet)
			}
			if prev, ok := seen[c.Name]; ok {
				return fmt.Errorf("card %q is on two sheets (%s and %s)", c.Name, prev, sheet)
			}
			seen[c.Name] = sheet
		}
	}
	return nil
}
